import re

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.
    
    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    # Split the input string by the space and convert it to a list of characters
    test_list = [c for c in test.split()]
    # Create a dictionary to count the occurrences of each character
    test_dict = {c: test_list.count(c) for c in test_list}
    # Sort the characters by their count in descending order
    test_sorted = sorted(test_dict, key=test_dict.get, reverse=True)
    # Create a dictionary to count the most common character and its count
    test_result = {c: test_dict[c] for c in test_sorted}
    return test_result
